function EXTRA(R,ICON){
 /* hook: a bench ammeter reading 4.50 A where 5 A should flow */
 ICON.ctMeter=(x,y)=>`<g transform="translate(${x} ${y})"><rect x="-130" y="-150" width="260" height="260" rx="26" fill="#343A40"/><rect x="-104" y="-122" width="208" height="92" rx="10" fill="#D3F9D8"/>${CT_T(0,-56,'4.50',{fs:64,fw:800,a:'middle',fill:CT_INK})}${CT_T(88,-42,'A',{fs:28,fw:800,a:'end',fill:CT_INK})}<circle cx="0" cy="40" r="44" fill="#495057" stroke="#ADB5BD" stroke-width="4"/>${CT_L(0,40,26,14,'#FFFFFF',6)}<circle cx="-70" cy="140" r="14" fill="${RED}"/><circle cx="70" cy="140" r="14" fill="#212529"/>${CT_poly([[-70,154],[-90,200],[-150,210]],RED,6)}${CT_poly([[70,154],[90,200],[150,210]],'#212529',6)}${CT_T(0,250,'should be 5 A',{fs:28,fw:800,a:'middle',fill:ORG})}</g>`;
 /* recap pictures: each fills most of its card (about 420 × 330) */
 ICON.ctComp=(x,y)=>`<g transform="translate(${x-210} ${y-165})"><rect x="-10" y="10" width="440" height="320" rx="18" fill="#EDF2FF"/>${CT_L(80,40,80,90,CT_INK,4)}${CT_resV(80,90,190,BLU,4,36)}${CT_T(108,148,'Z',{fs:30,fw:800,fill:BLU})}${CT_resV(80,190,280,ORG,4,32)}${CT_T(108,246,'ΔZ',{fs:30,fw:800,fill:ORG})}${CT_L(80,280,80,310,CT_INK,4)}${CT_arrow(170,175,240,175,CT_MUT,4)}${CT_L(330,40,330,90,CT_INK,4)}${CT_resV(330,90,190,BLU,4,36)}${CT_vs(330,240,34,ORG)}${CT_L(330,190,330,206,CT_INK,4)}${CT_L(330,274,330,310,CT_INK,4)}${CT_T(374,250,'IΔZ',{fs:30,fw:800,fill:ORG})}</g>`;
 ICON.ctPhasor=(x,y)=>{const ox=90,oy=150,k=60;return `<g transform="translate(${x-210} ${y-165})">${CT_L(30,oy,410,oy,CT_AX,3)}${CT_L(ox,20,ox,320,CT_AX,3)}${CT_arrow(ox,oy,ox+2*k,oy-1*k,BLU,6)}${CT_arrow(ox,oy,ox+1*k,oy+2*k,ORG,6)}${CT_T(ox+2*k+12,oy-1*k,'I₁ = 2 + j1 A',{fs:26,fw:800,fill:BLU})}${CT_T(ox+1*k+14,oy+2*k+10,'I₂ = 1 − j2 A',{fs:26,fw:800,fill:ORG})}${CT_T(400,oy-14,'real',{fs:22,fw:700,a:'end',fill:CT_MUT})}${CT_T(ox+10,40,'j',{fs:24,fw:800,fill:CT_MUT})}</g>`};
 ICON.ctMatch=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${CT_L(40,290,400,290,CT_AX,3)}<rect x="70" y="${290-20*10}" width="130" height="${20*10}" rx="8" fill="${CT_AX}"/><rect x="240" y="${290-25*10}" width="130" height="${25*10}" rx="8" fill="${GRN}"/>${CT_T(135,130,'20 W',{fs:30,fw:800,a:'middle',fill:'#FFFFFF'})}${CT_T(305,80,'25 W',{fs:30,fw:800,a:'middle',fill:'#FFFFFF'})}${CT_T(135,322,'4 + j4 Ω',{fs:24,fw:700,a:'middle',fill:CT_MUT})}${CT_T(305,322,'2 + j2 Ω',{fs:24,fw:800,a:'middle',fill:GRN})}</g>`;
}
